INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("トゥインクルウィッシュ", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "ヒヨリ", 155, "人助け、応援", "東山奈央", 44, "獣人族", 8, "A", "人助けが大好き！　前向き格闘娘", 2, 100101, 16, 0, 27);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("トゥインクルウィッシュ", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "ユイ", 158, "料理、人間観察", "種田梨沙", 47, "ヒューマン", 4, "O", "戦闘のサポートが得意な、心優しい少女", 2, 100201, 17, 0, 5);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("トゥインクルウィッシュ", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "レイ", 163, "読書、乗馬、お茶", "早見沙織", 46, "魔族", 1, "B", "クールで何事にも真っ直ぐな剣士", 2, 100301, 18, 0, 12);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("リトルリリカル", "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", "ミソギ", 128, "いたずら、探検", "諸星すみれ", 27, "ヒューマン", 8, "O", "探検好きのイタズラっ子", 5, 100401, 9, 0, 10);
