INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("悪魔偽王国軍（ディアボロス）", "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", "アカリ", 150, "サックス", "浅倉杏美", 42, "魔族", 11, "O", "甘え上手なみんなの人気者", 7, 100601, 13, 0, 22);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("悪魔偽王国軍（ディアボロス）", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "ミヤコ", 130, "プリンを食べること", "雨宮天", 32, "魔族", 1, "B", "プリン大好きゴースト娘", 7, 100701, 14, 0, 23);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヴァイスフリューゲル　ランドソル支部", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", "ユキ", 150, "鏡で自分を見ること", "大空直美", 40, "エルフ", 10, "AB", "ボクは誰よりも美しい", 15, 100801, 14, 0, 10);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("トワイライトキャラバン", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", "アンナ", 159, "小説執筆", "髙野麻美", 45, "魔族", 7, "A", "前世を信じる中二病患者、「疾風の冥姫」", 13, 100901, 17, 0, 5);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("自警団（カォン）", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "マホ", 155, "空想、ぬいぐるみ集め", "内田真礼", 42, "獣人族", 9, "O", "マホマホ王国のプリンセス", 10, 101001, 16, 0, 22);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ラビリンス", "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", "リノ", 156, "お裁縫", "阿澄佳奈", 44, "ヒューマン", 8, "A", "人懐っこくてマシンガントークな妹系少女", 3, 101101, 15, 0, 25);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("フォレスティエ", "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", "ハツネ", 156, "妹と遊ぶこと、二度寝、昼寝、早寝", "大橋彩香", 46, "エルフ", 12, "A", "みんなのために超能力を使う眠り姫", 6, 101201, 17, 0, 24);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("トワイライトキャラバン", "", "ナナカ", 166, "読書、魔法", "佳村はるか", 55, "魔族", 8, "O", "オタク全開な魔法少女", 13, 101301, 18, 0, 21);
