INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ルーセント学院", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", "スズナ", 167, "ファッション", "上坂すみれ", 48, "魔族", 4, "O", "天真爛漫で人気者のカリスマモデル", 14, 101601, 17, 0, 10);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("自警団（カォン）", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", "カオリ", 158, "踊り、空手", "高森奈津美", 53, "獣人族", 7, "A", "いつでも「なんくるないさ～」な天然娘", 10, 101701, 17, 0, 7);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ルーセント学院", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", "イオ", 162, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", "伊藤静", 52, "魔族", 8, "B", "多くの男性を魅了する無垢な女教師", 14, 101801, 23, 0, 14);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("リトルリリカル", "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", "ミミ", 117, "かわいいもの集め", "日高里菜", 21, "獣人族", 4, "O", "お歌もにんじんも、ウサギさんも大好き♪", 5, 102001, 10, 0, 3);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("サレンディア救護院", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "クルミ", 150, "観劇、おままごと", "植田佳奈", 40, "ヒューマン", 6, "B", "泣き虫で臆病な守ってあげたい女の子", 9, 102101, 12, 0, 9);
