INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("サレンディア救護院", "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", "スズメ", 154, "ご奉仕", "悠木碧", 43, "ヒューマン", 12, "O", "お嬢さまのためにがんばるドジっ娘メイド", 9, 102501, 15, 0, 12);
