INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("トワイライトキャラバン", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "エリコ", 154, "実験、裁縫、料理", "橋本ちなみ", 43, "魔族", 7, "B", "運命の相手に一途すぎる乙女", 13, 102701, 16, 0, 30);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("サレンディア救護院", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", "サレン", 156, "経営、お茶会", "堀江由衣", 43, "エルフ", 10, "A", "救護院を経営する優しい庶民派お嬢様", 9, 102801, 17, 0, 4);
