INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("自警団（カォン）", "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", "マコト", 168, "お菓子作り", "小松未可子", 54, "獣人族", 8, "O", "男勝りで情に厚いワイルド娘", 10, 104301, 17, 0, 9);
