INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("カルミナ", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "チカ（クリスマス）", 163, "各種楽器", "福原綾香", 46, "ヒューマン", 6, "O", "人々を守るために歌う、唱喚士の少女", 4, 108401, 17, 0, 3);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("サレンディア救護院", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "クルミ（クリスマス）", 150, "観劇、おままごと", "植田佳奈", 40, "ヒューマン", 6, "B", "泣き虫で臆病な守ってあげたい女の子", 9, 108501, 12, 0, 9);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("サレンディア救護院", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", "アヤネ（クリスマス）", 148, "屋内でできる遊び", "芹澤優", 38, "ヒューマン", 5, "B", "ぷうきちといつも一緒！", 9, 108601, 14, 0, 10);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("トゥインクルウィッシュ", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "ヒヨリ（ニューイヤー）", 155, "人助け、応援", "東山奈央", 44, "獣人族", 8, "A", "人助けが大好き！　前向き格闘娘", 2, 108701, 16, 0, 27);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("トゥインクルウィッシュ", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "ユイ（ニューイヤー）", 158, "料理、人間観察", "種田梨沙", 47, "ヒューマン", 4, "O", "戦闘のサポートが得意な、心優しい少女", 2, 108801, 17, 0, 5);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("トゥインクルウィッシュ", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "レイ（ニューイヤー）", 163, "読書、乗馬、お茶", "早見沙織", 46, "魔族", 1, "B", "クールで何事にも真っ直ぐな剣士", 2, 108901, 18, 0, 12);
